package com.sportradar.worldcup.scoreboard;

import com.sportradar.worldcup.scoreboard.exception.InvalidScoreException;
import com.sportradar.worldcup.scoreboard.exception.InvalidTeamException;

import java.util.Objects;

/**
 * Immutable snapshot of a match at the moment it was read.
 *
 * @param id         identifier generated by the library when the match was started
 * @param team1      first (home) team name, never null or blank
 * @param team2      second (away) team name, never null or blank
 * @param team1Score goals of {@code team1}, never negative
 * @param team2Score goals of {@code team2}, never negative
 */
public record MatchSummary(MatchId id,
                           String team1,
                           String team2,
                           int team1Score,
                           int team2Score) {

    public MatchSummary {
        Objects.requireNonNull(id, "id cannot be null");

        team1 = normalizeTeamName(team1, "team1");
        team2 = normalizeTeamName(team2, "team2");

        if (team1Score < 0) {
            throw new InvalidScoreException("team1Score cannot be negative: " + team1Score);
        }
        if (team2Score < 0) {
            throw new InvalidScoreException("team2Score cannot be negative: " + team2Score);
        }
    }

    /**
     * Normalizes and validates team name.
     * Used both by this record and by {@link Scoreboard}.
     */
    static String normalizeTeamName(String teamName, String fieldName) {
        Objects.requireNonNull(teamName, fieldName + " cannot be null");
        String normalized = teamName.strip();
        if (normalized.isEmpty()) {
            throw new InvalidTeamException(fieldName + " cannot be null, empty or blank");
        }
        return normalized;
    }
}